import { MuseClient } from '@muse-code/sdk';

const client = new MuseClient({ apiKey: process.env.META_API_KEY });
client.on('session/tokenUsage', (usage) => {
  console.log('Live token usage:', usage);
});
await client.send('/effort medium'); // Cap Muse Spark reasoning depth
await client.prompt('Audit auth routes and write unit tests');

